frappe.ui.form.on('POS Invoice', {
    setup: function(frm) {
        frm.set_query('custom_merged_pos_invoice', function() {
            if (frm.doc.name && !frm.doc.__islocal) {
                return {
                    filters: {
                        name: ['!=', frm.doc.name]
                    }
                };
            }
        });
    },
    custom_merged_pos_invoice: function(frm) {
        if(frm.doc.custom_merged_pos_invoice) {
            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "POS Invoice",
                    name: frm.doc.custom_merged_pos_invoice
                },
                callback: function(r) {
                    if(r.message && r.message.items) {
                        frm.clear_table("custom_merged_pos_invoice_details");
                        r.message.items.forEach(function(item) {
                            let row = frm.add_child("custom_merged_pos_invoice_details");
                            row.item_code = item.item_code;
                            row.item_name = item.item_name;
                            row.qty = item.qty;
                            row.rate = item.rate;
                            row.amount = item.amount;
                        });
                        frm.refresh_field("custom_merged_pos_invoice_details");
                    }
                }
            });
        } else {
            frm.clear_table("custom_merged_pos_invoice_details");
            frm.refresh_field("custom_merged_pos_invoice_details");
        }
    }
});
